using System.ClientModel;
using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool implementations -----------------------------------------------

/// <summary>Simple in-memory notebook the agent can write to and read from.</summary>
static class Notebook
{
    private static readonly List<string> _notes = [];

    [Description("Save a research note. Use this to record important facts, quotes, or findings while researching.")]
    public static string AddNote([Description("The note text to save")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";
        return string.Join("\n", _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }
}

/// <summary>Lightweight web search and page-fetch tools.</summary>
static class WebSearch
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" }
        },
        Timeout = TimeSpan.FromSeconds(15)
    };

    [Description("Search the web for a query. Returns a list of result titles and URLs. Use this to discover relevant pages.")]
    public static async Task<string> Search(
        [Description("The search query string")] string query)
    {
        try
        {
            // Use DuckDuckGo HTML-only endpoint (no API key needed)
            var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
            var html = await Http.GetStringAsync(url);

            var results = new List<string>();
            // Parse result links from the HTML (class="result__a")
            var span = html.AsSpan();
            int pos = 0;
            while (results.Count < 5)
            {
                int classIdx = html.IndexOf("class=\"result__a\"", pos, StringComparison.Ordinal);
                if (classIdx < 0) break;

                int hrefIdx = html.LastIndexOf("href=\"", classIdx, Math.Min(classIdx, 200), StringComparison.Ordinal);
                if (hrefIdx < 0) { pos = classIdx + 1; continue; }
                hrefIdx += 6;
                int hrefEnd = html.IndexOf('"', hrefIdx);
                var href = html[hrefIdx..hrefEnd];

                int tagClose = html.IndexOf('>', classIdx);
                int tagEnd = html.IndexOf('<', tagClose);
                var title = html[(tagClose + 1)..tagEnd].Trim();

                if (!string.IsNullOrWhiteSpace(title))
                    results.Add($"- {title}\n  {href}");
                pos = tagEnd;
            }

            return results.Count > 0
                ? $"Search results for \"{query}\":\n{string.Join("\n", results)}"
                : $"No results found for \"{query}\".";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Fetch the text content of a web page. Use this to read a page discovered via search.")]
    public static async Task<string> FetchPage(
        [Description("The full URL to fetch")] string url)
    {
        try
        {
            var html = await Http.GetStringAsync(url);

            // Rough HTML-to-text: strip tags, decode entities, trim whitespace
            var text = System.Text.RegularExpressions.Regex.Replace(html, "<script[^>]*>[\\s\\S]*?</script>", " ");
            text = System.Text.RegularExpressions.Regex.Replace(text, "<style[^>]*>[\\s\\S]*?</style>", " ");
            text = System.Text.RegularExpressions.Regex.Replace(text, "<[^>]+>", " ");
            text = System.Net.WebUtility.HtmlDecode(text);
            text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ").Trim();

            // Limit to ~4000 chars to stay within context limits
            if (text.Length > 4000)
                text = text[..4000] + "… [truncated]";

            return string.IsNullOrWhiteSpace(text)
                ? "Page returned no readable text."
                : text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }
}

// --- Agent setup --------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new ChatClientBuilder(
        new OpenAIClient(new ApiKeyCredential(apiKey))
            .GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()   // auto-invokes tools and feeds results back
    .Build();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(WebSearch.Search),
    AIFunctionFactory.Create(WebSearch.FetchPage),
    AIFunctionFactory.Create(Notebook.AddNote),
    AIFunctionFactory.Create(Notebook.GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

var systemPrompt = """
    You are a research agent. Given a topic, you:
    1. Search the web to find relevant pages.
    2. Fetch and read promising pages.
    3. Take notes on key findings using the note-taking tool.
    4. After collecting enough information, retrieve your notes and produce a
       concise, well-structured summary with references.
    Be thorough but efficient — aim for 2-3 searches and 2-4 page fetches.
    Always save important findings as notes before writing the final summary.
    """;

// --- Interactive loop ---------------------------------------------------

Console.WriteLine("🔍 Research Agent Ready (type 'exit' to quit)");
Console.WriteLine("Enter a topic to research:");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(topic) || topic.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a summary:\n\n{topic}")
    };

    Console.WriteLine("\nResearching…\n");

    var response = await client.GetResponseAsync(messages, chatOptions);

    Console.WriteLine(response.Text);
}

